"""Import role-private prime31 preprocessing generated by native MAMA.

The producer runs four malicious-protocol processes with live OT preprocessing.
It never aggregates MAC keys or re-shares their outputs. Each online process
imports only its own native persistence file and owner-only input-mask output.
These bundles support functional measurements only: the small-field native
preprocessing failed the privacy review and does not meet the security target.
"""
from __future__ import annotations

import hashlib
import json
import math
import os
from pathlib import Path
import secrets
import shutil
import socket
import struct
import subprocess
import sys
import tempfile
import time

import numpy as np
import torch

from .spdz import PRIME
from .spdz_distributed import AuthShare,MatrixTriple
from .spdz_inputs import InputMask
from .spdz_polynomial import SquareMask

MAC_KEYS=10
_FORMAT='mama-prime31-role-v1'
_SPEC=b'Mama10 gfp'+b'\x00'+struct.pack('<I',4)+PRIME.to_bytes(4,'big')+struct.pack('<I',1)
_INV_R=pow(pow(2,64,PRIME),-1,PRIME)


def _sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def _shape(shape):
    if len(shape)!=2 or any(type(n) is not int or not 1<=n<2**31 for n in shape):
        raise ValueError('preprocessing shapes must contain two positive int32 dimensions')
    return list(shape)


def _layout(request,session):
    records=[]
    clear_offsets=[0]*4
    offset=0
    def add(kind,name,component,shape,owner=None):
        nonlocal offset
        shape=_shape(shape)
        context=json.dumps([kind,name,shape,owner],separators=(',',':')).encode()
        identifier=hashlib.sha256(bytes.fromhex(session)+context).hexdigest()
        record=dict(kind=kind,name=name,component=component,shape=shape,offset=offset,
                    count=math.prod(shape),identifier=identifier)
        if owner is not None:
            record['owner']=owner
            record['clear_offset']=clear_offsets[owner]
            clear_offsets[owner]+=record['count']
        records.append(record)
        offset+=record['count']
    add('calibration','constant_one','value',[1,1])
    for kind in ('matrices','squares','inputs'):
        names=set()
        for item in request.get(kind,[]):
            name=item['name']
            if not isinstance(name,str) or not name or name in names:
                raise ValueError('correlation names must be unique nonempty strings within each kind')
            names.add(name)
            if kind=='matrices':
                m,k,n=item['m'],item['k'],item['n']
                for component,shape in [('a',[m,k]),('b',[k,n]),('c',[m,n])]:
                    add(kind,name,component,shape)
            elif kind=='squares':
                for component in ('a','a_squared'):add(kind,name,component,item['shape'])
            else:
                owner=item['owner']
                if type(owner) is not int or owner not in range(4):raise ValueError('input owner must be in [0,3]')
                add(kind,name,'share',item['shape'],owner)
    return records,offset,clear_offsets


def _program(request):
    lines=['from Compiler.types import sint,cint,regint,Matrix',
           'from Compiler.instructions import inputmaskreg',
           'from Compiler.library import check_point,print_ln',
           'check_point()', 'sint.write_to_file(sint(1))']
    for index,item in enumerate(request.get('matrices',[])):
        m,k,n=item['m'],item['k'],item['n']
        lines += [f'a{index}=Matrix({m},{k},sint)',f'b{index}=Matrix({k},{n},sint)',
                  f'a{index}.assign_vector(sint.get_random(size={m*k}))',
                  f'b{index}.assign_vector(sint.get_random(size={k*n}))',
                  f'c{index}=a{index}.dot(b{index})','check_point()']
        lines += [f'sint.write_to_file({component}{index}.get_vector())' for component in ('a','b','c')]
    for index,item in enumerate(request.get('squares',[])):
        count=math.prod(item['shape'])
        lines += [f'sq{index},sqc{index}=sint.get_random_square(size={count})','check_point()',
                  f'sint.write_to_file([sq{index},sqc{index}])']
    for index,item in enumerate(request.get('inputs',[])):
        count=math.prod(item['shape'])
        lines += [f'im{index}=sint(size={count})',f'ic{index}=cint(size={count})',
                  f'inputmaskreg(im{index},ic{index},regint({item["owner"]},size={count}))',
                  'check_point()',f'sint.write_to_file(im{index})',f'ic{index}.to_regint(n_bits=0,sync=False).binary_output({item["owner"]})']
    lines += ['check_point()',"print_ln('MAMA preprocessing export checks complete')"]
    return '\n'.join(lines)+'\n'


def _binary(native_root):
    root=Path(native_root).resolve()
    for candidate in (root/'mama-party.x',root/'bin/Linux-adx/mama-party.x'):
        if candidate.is_file():return candidate
    raise FileNotFoundError('native MAMA executable was not found')


def _verify_policy(native_root,binary):
    """Check the reviewed build provenance; this is not remote attestation."""
    repository=Path(__file__).resolve().parents[1]
    policy_path=native_root/'native-preprocessing-policy.json'
    policy=json.loads(policy_path.read_text())
    expected=dict(format='mama-prime31-reviewed-build-v1',prime=PRIME,mac_keys=MAC_KEYS,
                  security_parameter=128,ot='SoftSpokenMalOt',
                  build_properties=dict(LONG_BIT_MAC_KEY=True,USE_KOS=0,USE_LIBOTE2=0,INSECURE=False))
    if any(policy.get(k)!=v for k,v in expected.items()):raise ValueError('unreviewed native preprocessing policy')
    lock_path=repository/'native/mama-source-lock.json'
    patch_path=repository/'native/patches/mama-independent-sacrifice.patch'
    if policy.get('source_lock_sha256')!=_sha(lock_path) or policy.get('reviewed_patch_sha256')!=_sha(patch_path):
        raise ValueError('native policy does not match the reviewed source lock and patch')
    lock=json.loads(lock_path.read_text())
    if lock['patch_sha256']!=_sha(patch_path) or (native_root/'CONFIG.mine').read_text()!=lock['config']:
        raise ValueError('native build configuration or sacrifice patch differs from the reviewed lock')
    if policy.get('binary_sha256')!=_sha(binary):raise ValueError('native executable differs from its policy')
    required={'CONFIG','CONFIG.mine','Machines/mama-party.cpp','Protocols/MamaPrep.hpp',
              'Protocols/ShuffleSacrifice.hpp','Protocols/MAC_Check.hpp','OT/NPartyTripleGenerator.hpp',
              'OT/OTExtensionWithMatrix.cpp','OT/OTMultiplier.hpp','OT/MascotMacKey.hpp'}
    if not required<=policy.get('source_sha256',{}).keys():raise ValueError('incomplete native source policy')
    dependencies={'libSPDZ.so','local/lib/liblibOTe.a','local/lib/libcryptoTools.a','local/lib/libsodium.so'}
    if not dependencies<=policy.get('dependency_sha256',{}).keys():raise ValueError('incomplete native dependency policy')
    for category in ('source_sha256','dependency_sha256'):
        for name,digest in policy[category].items():
            path=(native_root/name).resolve()
            if Path(name).is_absolute() or '..' in Path(name).parts or _sha(path)!=digest:
                raise ValueError(f'native policy file mismatch: {name}')
    for name,digest in lock['source_files_sha256'].items():
        if name!='Protocols/MamaPrep.hpp' and _sha(native_root/name)!=digest:
            raise ValueError(f'native source differs from reviewed upstream: {name}')
    # Verify the actual modified header is exactly the locked upstream plus
    # the reviewed patch, rather than accepting a self-declared patch marker.
    with tempfile.TemporaryDirectory(prefix='mama-policy-') as temporary:
        restored=Path(temporary)/'MamaPrep.hpp'
        checked=subprocess.run(['patch','--batch','--reverse','--output',str(restored),
                                '--input',str(patch_path),str(native_root/'Protocols/MamaPrep.hpp')],
                               capture_output=True)
        if checked.returncode or _sha(restored)!=lock['source_files_sha256']['Protocols/MamaPrep.hpp']:
            raise ValueError('native MAMA header is not the reviewed patched upstream')
    return policy,_sha(policy_path)


def _native_environment(native_root,binary,policy):
    # Pin private libraries and ignore ambient dynamic-loader overrides. This
    # records local provenance; it cannot attest a remote host's behavior.
    environment={k:v for k,v in os.environ.items() if not k.startswith('LD_')}
    environment.update(LD_LIBRARY_PATH=f'{native_root}/local/lib:{native_root}',OMP_NUM_THREADS='1')
    inspected=subprocess.run(['ldd',str(binary)],env=environment,capture_output=True,text=True,timeout=15)
    if inspected.returncode:raise ValueError('cannot resolve native shared libraries')
    resolved={}
    for line in inspected.stdout.splitlines():
        if '=>' not in line:continue
        name,target=line.split('=>',1)
        path=target.strip().split()[0]
        if path.startswith('/'):
            actual=Path(path).resolve()
            resolved[name.strip()]={'path':str(actual),'sha256':_sha(actual)}
    required={'libSPDZ.so':(native_root/'libSPDZ.so','libSPDZ.so'),
              'libsodium':(native_root/'local/lib/libsodium.so','local/lib/libsodium.so')}
    for name,(path,policy_name) in required.items():
        matches=[entry for library,entry in resolved.items() if library==name or (name=='libsodium' and library.startswith('libsodium.so'))]
        if len(matches)!=1 or matches[0]['path']!=str(path.resolve()) or matches[0]['sha256']!=policy['dependency_sha256'][policy_name]:
            raise ValueError(f'native dynamic loader did not select the pinned {name}')
    return environment,resolved


def _port_base():
    # Bind four consecutive ports before releasing them for the native mesh.
    for _ in range(100):
        base=20000+secrets.randbelow(30000)
        held=[]
        try:
            for p in range(4):
                sock=socket.socket();sock.bind(('127.0.0.1',base+p));held.append(sock)
            return base
        except OSError:
            pass
        finally:
            for sock in held:sock.close()
    raise RuntimeError('cannot reserve native port range')


def run_native(manifest_path,output_dir,*,native_root='/home/zeb/Desktop/mp-spdz-toy/MP-SPDZ',
               timeout=900,batch_size=1000):
    """Generate fresh native role bundles; return public status and timing.

    ``output_dir`` must not exist. No fake/file preprocessing or insecure flags
    are accepted. Existing native sources and executables are read-only inputs.
    Failed output directories stay unready and their correlations cannot load.
    """
    request=json.loads(Path(manifest_path).read_text()) if not isinstance(manifest_path,dict) else manifest_path
    if not math.isfinite(timeout) or timeout<=0 or type(batch_size) is not int or batch_size<1:raise ValueError('invalid native timeout or batch size')
    session=secrets.token_hex(32)
    records,total,clear_counts=_layout(request,session)
    output=Path(output_dir).resolve();output.mkdir(parents=True,exist_ok=False,mode=0o700)
    native_root=Path(native_root).resolve();binary=_binary(native_root)
    policy,policy_hash=_verify_policy(native_root,binary)
    native_env,loaded_libraries=_native_environment(native_root,binary,policy)
    compiler=output/'compiler'
    for directory in ('Source','Bytecode','Schedules'):(compiler/'Programs'/directory).mkdir(parents=True,exist_ok=True)
    program='python_mama_export'
    source=compiler/'Programs/Source'/f'{program}.mpc';source.write_text(_program(request))
    metadata=dict(format=_FORMAT,ready=False,parties=4,prime=PRIME,mac_keys=MAC_KEYS,
                  security_parameter=128,session=session,request=request,records=records,
                  privacy_audit_status='failed_small_field_selective_failure',
                  security_target_met=False,functional_only=True,
                  share_count=total,clear_counts=clear_counts,
                  native_binary=str(binary),native_binary_sha256=_sha(binary),
                  native_policy=policy,native_policy_sha256=policy_hash,native_loaded_libraries=loaded_libraries,
                  export_source_sha256=_sha(source),native_source_sha256={})
    for name in ('CONFIG','CONFIG.mine','compile.py','Machines/mama-party.cpp','Protocols/MamaPrep.hpp','Protocols/ShuffleSacrifice.hpp',
                 'Protocols/MAC_Check.hpp','OT/NPartyTripleGenerator.hpp','OT/OTExtensionWithMatrix.cpp',
                 'OT/OTMultiplier.hpp','OT/MascotMacKey.hpp'):
        path=native_root/name
        if path.is_file():metadata['native_source_sha256'][name]=_sha(path)
    started=time.perf_counter()
    compile_log=compiler/'compile.log'
    with compile_log.open('w') as log:
        compiled=subprocess.run([sys.executable,'-B',str(native_root/'compile.py'),'-F','31',program],
                                cwd=compiler,stdout=log,stderr=subprocess.STDOUT,
                                env={**os.environ,'PYTHONDONTWRITEBYTECODE':'1'},timeout=timeout)
    if compiled.returncode:
        metadata.update(return_codes=[],passed=False,compile_return_code=compiled.returncode)
        (output/'public-manifest.json').write_text(json.dumps(metadata,indent=2)+'\n')
        return metadata
    compile_ms=(time.perf_counter()-started)*1000
    certs=output/'public-certificates';certs.mkdir()
    roles=[]
    def openssl(*args):
        subprocess.run(['openssl',*map(str,args)],check=True,capture_output=True,timeout=60)
    for p in range(4):
        role=output/f'party{p}';role.mkdir(mode=0o700)
        player=role/'Player-Data';player.mkdir(mode=0o700)
        (role/'Programs').symlink_to(compiler/'Programs',target_is_directory=True)
        openssl('req','-x509','-newkey','ec','-pkeyopt','ec_paramgen_curve:prime256v1','-nodes',
                '-keyout',player/f'P{p}.key','-out',certs/f'P{p}.pem','-days','1','-subj',f'/CN=P{p}')
        (player/f'P{p}.key').chmod(0o600)
        roles.append(role)
    for role in roles:
        for cert in certs.glob('*.pem'):shutil.copy2(cert,role/'Player-Data'/cert.name)
        openssl('rehash',role/'Player-Data')
    base=_port_base();processes=[];logs=[]
    native_started=time.perf_counter()
    try:
        for p,role in enumerate(roles):
            log=(role/'native.log').open('w');logs.append(log)
            command=[str(binary),'-p',str(p),'-N','4','-P',str(PRIME),'-lgp','31',
                     '-S','128','-e','-pn',str(base),'-b',str(batch_size),program]
            processes.append(subprocess.Popen(command,cwd=role,stdout=log,stderr=subprocess.STDOUT,
                                              env=native_env))
        deadline=time.monotonic()+timeout
        for process in processes:process.wait(timeout=max(.001,deadline-time.monotonic()))
    except BaseException as error:
        metadata['error']=f'{type(error).__name__}: {error}'
    finally:
        for process in processes:
            if process.poll() is None:process.kill()
        for process in processes:process.wait()
        for log in logs:log.close()
    codes=[process.returncode for process in processes]
    passed=len(codes)==4 and all(code==0 for code in codes)
    metadata.update(ready=passed,passed=passed,return_codes=codes,compile_ms=compile_ms,
                    native_preprocessing_ms=(time.perf_counter()-native_started)*1000,
                    preprocessing_ms=(time.perf_counter()-started)*1000,
                    private_role_directories=[str(role) for role in roles],
                    transport='native encrypted peer channels',trusted_dealer=False)
    encoded=json.dumps(metadata,indent=2)+'\n'
    (output/'public-manifest.json').write_text(encoded)
    for role in roles:
        (role/'public-manifest.json').write_text(encoded)
        (role/'native-policy.json').write_text((native_root/'native-preprocessing-policy.json').read_text())
        # No native secret file is copied between roles or read by this coordinator.
        for private in (role/'Player-Data').glob('Mascot-Secrets-*'):private.chmod(0o600)
        for private in (role/'Persistence').glob('*') if (role/'Persistence').exists() else []:private.chmod(0o600)
        for private in (role/'Player-Data').glob('Binary-Output-*'):private.chmod(0o600)
    return metadata


def _native_file(path,count):
    raw=Path(path).read_bytes()
    if len(raw)<8:raise ValueError('truncated native persistence header')
    header_size=struct.unpack('<Q',raw[:8])[0]
    if header_size!=len(_SPEC)+8*MAC_KEYS:raise ValueError('unsupported native protocol header length')
    header=raw[8:8+header_size]
    if header[:len(_SPEC)]!=_SPEC:raise ValueError('native MAMA type, prime, or Montgomery format mismatch')
    if len(raw)!=8+header_size+count*8*(MAC_KEYS+1):raise ValueError('native share count or file length mismatch')
    words=np.frombuffer(raw[8+header_size:],dtype='<u8').reshape(count,MAC_KEYS+1)
    alpha=np.frombuffer(header[len(_SPEC):],dtype='<u8')
    if np.any(words>=PRIME) or np.any(alpha>=PRIME):raise ValueError('noncanonical native Montgomery value')
    # Both factors are below2**31, so this product remains below signed2**63.
    decoded=(words.astype(np.int64)*_INV_R)%PRIME
    key=(alpha.astype(np.int64)*_INV_R)%PRIME
    return decoded,key


def load_role(bundle_path,party,device='cpu',*,storage_dtype=torch.int64,online_mac_keys=MAC_KEYS):
    """Load only role ``party`` and atomically retire its bundle for reuse.

    This must run inside the assigned online worker, not a coordinator that
    aggregates roles. Correlations and keys from a failed session stay retired.
    The shared-account test harness is not an OS boundary against hostile code.
    ``storage_dtype=torch.int32`` packs canonical shares before device upload;
    use it only with an online backend supporting int32 storage. MAC keys and
    owner clear masks retain int64. Native preprocessing always uses ten keys.
    ``online_mac_keys=7`` selects the fixed first seven only after validating
    and calibrating all ten; unused coordinates remain retired with the whole
    bundle. The session binds this ordered selection. See
    ``docs/online-mac-bounds.md`` for the online-check bound and assumptions.
    """
    if type(online_mac_keys) is not int or online_mac_keys not in (7,MAC_KEYS):
        raise ValueError('online MAC selection must contain exactly seven or ten keys')
    indices=tuple(range(online_mac_keys))
    if storage_dtype not in (torch.int32,torch.int64):
        raise ValueError('native share storage must be int32 or int64')
    numpy_dtype=np.int32 if storage_dtype==torch.int32 else np.int64
    role=Path(bundle_path).resolve()
    manifest=json.loads((role/'public-manifest.json').read_text())
    if manifest.get('format')!=_FORMAT or not manifest.get('ready') or manifest.get('return_codes')!=[0]*4:
        raise ValueError('native preprocessing did not complete all checks')
    if party not in range(4) or role.name!=f'party{party}':raise ValueError('role path does not match assigned party')
    if manifest.get('native_policy_sha256')!=_sha(role/'native-policy.json'):
        raise ValueError('native role policy was changed after preprocessing')
    if manifest.get('native_policy')!=json.loads((role/'native-policy.json').read_text()):
        raise ValueError('native role policy does not match its public manifest')
    policy=manifest['native_policy']
    repository=Path(__file__).resolve().parents[1]
    if (policy.get('format')!='mama-prime31-reviewed-build-v1' or policy.get('prime')!=PRIME
            or policy.get('mac_keys')!=MAC_KEYS or policy.get('security_parameter')!=128
            or policy.get('ot')!='SoftSpokenMalOt'
            or policy.get('binary_sha256')!=manifest.get('native_binary_sha256')
            or policy.get('source_lock_sha256')!=_sha(repository/'native/mama-source-lock.json')
            or policy.get('reviewed_patch_sha256')!=_sha(repository/'native/patches/mama-independent-sacrifice.patch')
            or policy.get('build_properties')!=dict(LONG_BIT_MAC_KEY=True,USE_KOS=0,USE_LIBOTE2=0,INSECURE=False)):
        raise ValueError('native role metadata does not match the reviewed preprocessing policy')
    if manifest.get('parties')!=4 or manifest['prime']!=PRIME or manifest['mac_keys']!=MAC_KEYS or manifest['security_parameter']!=128:
        raise ValueError('native preprocessing security or field parameters mismatch')
    fd=os.open(role/'consumed',os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600)
    with os.fdopen(fd,'w') as marker:
        marker.write(json.dumps(dict(native_session=manifest['session'],native_mac_keys=MAC_KEYS,
                                     online_mac_keys=online_mac_keys,online_mac_indices=list(indices)),sort_keys=True)+'\n')
        marker.flush()
        os.fsync(marker.fileno())
    directory_fd=os.open(role,os.O_RDONLY|os.O_DIRECTORY)
    try:os.fsync(directory_fd)
    finally:os.close(directory_fd)
    records,count,clear_counts=_layout(manifest['request'],manifest['session'])
    if records!=manifest['records'] or count!=manifest['share_count'] or clear_counts!=manifest['clear_counts']:
        raise ValueError('native preprocessing layout mismatch')
    data,key=_native_file(role/'Persistence'/f'Transactions-P{party}.data',count)
    calibration=data[0]
    if calibration[0]!=(1 if party==0 else 0) or not np.array_equal(calibration[1:],key):
        raise ValueError('native constant-one calibration failed')
    clear_path=role/'Player-Data'/f'Binary-Output-P{party}-0'
    clear_raw=clear_path.read_bytes() if clear_path.exists() else b''
    if len(clear_raw)!=clear_counts[party]*8:raise ValueError('owner-only clear input-mask count mismatch')
    clear=np.frombuffer(clear_raw,dtype='<i8')
    if np.any(clear<0) or np.any(clear>=PRIME):raise ValueError('noncanonical clear input mask')
    matrices={};squares={};inputs={}
    def share(record):
        offset,n=record['offset'],record['count'];shape=record['shape']
        local=data[offset:offset+n]
        return AuthShare(torch.from_numpy(local[:,0].astype(numpy_dtype,copy=True)).reshape(shape).to(device),
                         torch.from_numpy(local[:,1:1+online_mac_keys].T.astype(numpy_dtype,copy=True,order='C')).reshape(online_mac_keys,*shape).to(device))
    for record in records[1:]:
        kind,name,component=record['kind'],record['name'],record['component']
        destination=matrices if kind=='matrices' else squares if kind=='squares' else inputs
        destination.setdefault(name,{})[component]=share(record)
    for item in manifest['request'].get('matrices',[]):
        name=item['name'];parts=matrices[name]
        identifier=next(r['identifier'] for r in records if r['kind']=='matrices' and r['name']==name and r['component']=='a')
        matrices[name]=MatrixTriple(parts['a'],parts['b'],parts['c'],identifier=bytes.fromhex(identifier))
    for item in manifest['request'].get('squares',[]):
        name=item['name'];parts=squares[name]
        identifier=next(r['identifier'] for r in records if r['kind']=='squares' and r['name']==name and r['component']=='a')
        squares[name]=SquareMask(parts['a'],parts['a_squared'],bytes.fromhex(identifier))
    for record in records:
        if record['kind']=='inputs':
            start=record['clear_offset'];n=record['count']
            value=(torch.from_numpy(clear[start:start+n].copy()).reshape(record['shape']).to(device)
                   if party==record['owner'] else None)
            inputs[record['name']]=InputMask(inputs[record['name']]['share'],value,record['owner'],bytes.fromhex(record['identifier']))
    native_session=bytes.fromhex(manifest['session'])
    selection=(b'SPDZ31-MAMA-online-selection-v1\x00'+struct.pack('<Q',len(native_session))+native_session
               +struct.pack('<II',MAC_KEYS,len(indices))+b''.join(struct.pack('<I',index) for index in indices))
    session=hashlib.sha256(selection).digest()
    provenance={name:manifest[name] for name in ('format','native_binary_sha256','native_source_sha256',
                                              'export_source_sha256','native_policy_sha256','preprocessing_ms','native_preprocessing_ms')}
    provenance.update(native_mac_keys=MAC_KEYS,online_mac_keys=online_mac_keys,online_mac_indices=list(indices),
                      privacy_audit_status='failed_small_field_selective_failure',security_target_met=False,functional_only=True,
                      session_derivation='SHA256 of framed native session, native key count, and ordered online key indices v1')
    return dict(alpha_share=torch.from_numpy(key[:online_mac_keys].copy()).to(device),matrix_triples=matrices,
                square_masks=squares,input_masks=inputs,session=session,provenance=provenance)
